(() => {
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const root='#/support';
  const topics=[['faq','FAQ'],['deposit','Deposit Not Receive'],['withdrawal','Withdrawal problem'],['ifsc','IFSC Modification'],['bank-rebind','Delete Withdraw Bank Account and Rebind'],['upi-rebind','Delete UPI and Rebind'],['password','Change ID Login Password'],['bank-name','Change bank name'],['usdt-rebind','Delete Old USDT Address and Rebind'],['game','Game Problems'],['official','Official Channel']];
  const rebind=['bank-rebind','upi-rebind','usdt-rebind'];
  const labels=Object.fromEntries(topics);
  const img=id=>`<img src="assets/${id==='game'?'support/game-problem.svg':id==='official'?'support/colorwin-crown.svg':'support/'+id+'.png'}" alt="">`;
  const preview=()=>window.ColorWinAuth.session?.user?.id==='preview';
  const header=(title,back=root,language=true)=>`<header class="cs-header"><a href="${back}" aria-label="Go back">‹</a><h1>${esc(title)}</h1>${language?'<button type="button" data-language aria-label="Language: English"><img class="cs-language-flag" src="assets/web images/flag-en.png" alt=""></button>':'<span aria-hidden="true"></span>'}</header>`;
  const empty=text=>`<div class="cs-empty">${!text||/^No /i.test(text)?'<img class="cw-no-data-art" src="assets/no-data.svg" alt="" aria-hidden="true">':''}<p>${esc(text||'No Data')}</p></div>`;
  const button=(text,href)=>`<a href="${href}" class="cs-primary">${text}</a>`;
  const field=(name,label,placeholder=label,extra='')=>`<label class="cs-field"><span>${esc(label)} <b>*</b></span><input name="${name}" placeholder="${esc(placeholder)}" aria-label="${esc(label)}" required maxlength="100" ${extra}></label>`;
  const fileSpec=name=>name==='video'?{types:['video/mp4','video/quicktime','video/x-msvideo','video/x-matroska','video/x-ms-wmv'],ext:['mp4','mov','avi','mkv','wmv'],mb:50}:name==='statement'?{types:['application/pdf'],ext:['pdf'],mb:50}:{types:['image/jpeg','image/png','image/webp'],ext:['jpg','jpeg','png','webp'],mb:10};
  const validFile=(name,file)=>{const spec=fileSpec(name);return file&&file.size>0&&spec.types.includes(file.type)&&spec.ext.includes(file.name.split('.').pop().toLowerCase())&&file.size<=spec.mb*1024*1024;};
  const upload=(name,label,required=true,video=false)=>{const spec=fileSpec(name),kind=video==='pdf'?'PDF':video?'Video':'Photo';return `<div class="cs-field"><span>${esc(label)}${required?' <b>*</b>':''}</span><label class="cs-upload"><input type="file" name="${name}" aria-label="${esc(label)}" accept="${spec.types.join(',')}" ${required?'required':''}><span class="cs-upload-symbol">${kind==='Video'?'▷':kind==='PDF'?'▤':'＋'}</span><small>${kind}</small></label><div class="cs-file-info" data-file-info="${name}" role="status"></div><p class="cs-hint">${spec.ext.join(' / ').toUpperCase()} · Maximum ${spec.mb} MB</p></div>`;};
  const tips=()=>'<section class="cs-tips"><h2>Kind tips</h2><p>1. Select the relevant question and submit your details for review. Our support team will review your request.</p><p>2. Use Progress Query to view the status and response to your submitted work order.</p></section>';
  const faq=[['Deposit not received','Check your deposit history and payment status. If your payment succeeded but the deposit is missing, submit the order number, transfer reference and payment receipt using Deposit Not Receive.'],['Withdrawal problem','Open Withdrawal problem and select the relevant request. Include a clear description and supporting receipt if available. Support will review the order; submitting a ticket does not change its payment status.'],['How do I change payout details?','Choose the bank, UPI or USDT rebind option. Provide your existing account details and the requested proof. Changes are reviewed before they can be applied.'],['How do I check my request?','Open Progress Query to see your work orders. Tap an order to read the details, current status and support response.'],['How do I change my password?','If you know your current password, use Settings → Login password. Enter your current password, choose a new password, confirm it and save your changes.']];
  const socials=[
    ['telegram','Telegram','Join our community'],
    ['instagram','Instagram','Photos, stories and updates'],
    ['x','X','Follow the latest updates'],
    ['youtube','YouTube','Watch our latest videos'],
    ['facebook','Facebook','Connect with our community']
  ];
  function socialHref(id){
    const value=window.ColorWinSocialLinks?.[id];if(!value)return '';
    try{const url=new URL(value);const hosts={telegram:['t.me','telegram.me'],instagram:['instagram.com'],x:['x.com','twitter.com'],youtube:['youtube.com','youtu.be'],facebook:['facebook.com','fb.com']};
      return url.protocol==='https:'&&!url.username&&!url.password&&hosts[id].some(host=>url.hostname===host||url.hostname.endsWith('.'+host))?url.href:'';
    }catch{return '';}
  }
  function officialView(){return `<main class="cs-content"><section class="cs-social-hero"><img src="assets/support/colorwin-crown.svg" alt="Color Win"><h2>Stay connected with Color Win</h2><p>Choose a platform to visit our social channel.</p></section><nav class="cs-social-list" aria-label="Color Win social channels">${socials.map(([id,name,description])=>{
    const href=socialHref(id),content=`<img class="cs-social-icon" src="assets/social/${id}.png" alt="" width="43" height="43"><span class="cs-social-copy"><strong>${name}</strong><small>${href?description:'Link coming soon'}</small></span><span class="cs-social-arrow" aria-hidden="true">${href?'↗':'—'}</span>`;
    return href?`<a class="cs-social-card" href="${esc(href)}" target="_blank" rel="noopener noreferrer" aria-label="Open Color Win ${name} in a new tab">${content}</a>`:`<button type="button" class="cs-social-card" disabled aria-label="${name} link coming soon">${content}</button>`;
  }).join('')}</nav><a class="cs-text-link" href="#/account/notifications/information">View platform announcements ›</a></main>`;}
  function form(topic,mode){
    let fields='';
    if(topic==='deposit')fields=`<input type="hidden" name="deposit_id"><p class="cs-hint" data-deposit-status role="status">Loading selected order…</p>`+field('order_number','Order Number','Select an order','readonly')+field('amount','Order Amount','Select an order','readonly')+field('receiver_upi','Receiver UPI ID','Loading receiver UPI ID','readonly')+field('utr','UTR Number','Enter UTR number')+upload('receipt','Deposit proof screenshot')+'<section class="cs-upload-guidelines"><h2>Image Upload Guidelines</h2><p>Please ensure the uploaded image clearly shows the UTR/UPI number.</p></section><section data-aged-proof hidden><p class="cs-note">For deposits older than 24 hours, also upload a statement video recorded from a second device and a PDF bank statement.</p>'+upload('video','Statement video',false,true)+upload('statement','PDF bank statement',false,'pdf')+'</section>';
    if(topic==='withdrawal')fields=field('order_number','Order Number','Enter withdrawal order number')+upload('receipt','Withdrawal Voucher',false);
    if(topic==='ifsc')fields=field('ifsc','Correct IFSC Code','Please enter the correct IFSC code','pattern="[A-Za-z]{4}0[A-Za-z0-9]{6}"')+field('bank_number','Bank number','Please enter Bank Card Number','inputmode="numeric" pattern="[0-9]{6,30}"');
    if(topic==='bank-name')fields=`<div class="cs-field"><span>Correct bank name <b>*</b></span><button type="button" id="cs-choose-bank" class="cs-bank-select" aria-label="Correct bank name" aria-haspopup="dialog"><span>Please select a bank card name</span><b>›</b></button><input type="hidden" name="bank_name"></div>`+field('bank_number','Bank number','Please enter Bank Card Number','inputmode="numeric" pattern="[0-9]{6,30}"');
    if(rebind.includes(topic)){
      const account=topic==='bank-rebind'?field('bank_number','Bank account','Enter your old bank account number','inputmode="numeric" pattern="[0-9]{6,30}"'):topic==='upi-rebind'?field('upi','UPI account','Enter your old UPI ID','pattern="[A-Za-z0-9._-]+@[A-Za-z0-9.-]+"'):topic==='usdt-rebind'?field('usdt','Old USDT address','Enter your old TRC20 address','pattern="T[1-9A-HJ-NP-Za-km-z]{33}"'):'';
      fields=account+'<p class="cs-note">Support will verify account ownership before applying any change.</p>'+upload('identity','Selfie holding your ID card')+(topic==='bank-rebind'?upload('passbook','Old Passbook Bank'):'')+upload('receipt','Latest Deposit Receipt Proof');
    }
    if(!['ifsc','bank-name','deposit'].includes(topic))fields+=`<label class="cs-field"><span>${topic==='game'?'Explain the issue inside the game clearly and in detail':'Describe the issue'} <b>*</b></span><textarea name="message" aria-label="Describe the issue" placeholder="Please enter content" minlength="10" maxlength="500" required></textarea><small class="cs-counter">0/500</small></label>`;
    if(topic==='game')fields+=upload('screenshot','Attach clear screenshot photo',false)+upload('video','Attach clear video of the problem',false,true);
    return `<form id="cs-request" data-topic="${topic}" data-mode="${esc(mode||'signed-in')}" class="cs-form">${fields}<p class="cs-hint">Your attachments are shared privately with Color Win support for this request.</p><footer class="cs-footer"><button class="cs-primary" type="submit">Confirm</button></footer></form>`;
  }
  function otpView(topic){return `<form class="cs-form" id="cs-otp"><label class="cs-field"><span>Registered phone number to receive OTP <b>*</b></span><input name="phone" type="tel" aria-label="Registered phone number" placeholder="Enter your registered phone number" maxlength="16" required pattern="[+]?[0-9]{8,15}"></label><button type="button" class="cs-primary" id="cs-otp-send">Send Verification Code</button><p class="cs-note cs-otp-note">SMS verification is not enabled for Color Win yet. Use manual verification to send your request for review.</p><a class="cs-text-link" href="${root}/${topic}/manual">Cannot receive a code? Submit a manual request ›</a><footer class="cs-footer"><button class="cs-primary" type="submit" disabled>Confirm</button></footer></form>`;}
  function view(route){
    const [part,sub,mode]=route.replace(root,'').split('/').filter(Boolean);let title=labels[part]||'Self Service Center',body='',back=part?root:'#/account';
    if(part==='password')return window.ColorWinAccount.view('#/account/settings/password');
    if(!part)body=`<img class="cs-banner" src="assets/support/banner.png" alt="Color Win Self Service Center"><main class="cs-content"><h2 class="cs-section-heading">Self Service</h2><nav class="cs-menu" aria-label="Support topics">${topics.map(([id,label])=>`<a href="${id==='password'?'#/account/settings/password':root+'/'+id}" ${rebind.includes(id)?`data-choice="${id}"`:''}>${img(id)}<span>${label}</span><b>›</b></a>`).join('')}</nav>${tips()}</main><footer class="cs-footer">${button('Progress Query',root+'/progress')}</footer>`;
    else if(part==='faq')body=`<main class="cs-content"><section class="cs-faq">${faq.map(([q,a])=>`<details><summary>${esc(q)}<span>＋</span></summary><p>${esc(a)}</p></details>`).join('')}</section>${tips()}${button('Progress Query',root+'/progress')}</main>`;
    else if(part==='official')body=officialView();
    else if(part==='progress'){title='Progress Query';body='<main class="cs-content"><div class="cs-tabs" role="tablist"><button role="tab" aria-selected="true" data-status="all">All</button><button role="tab" aria-selected="false" data-status="open">In progress</button><button role="tab" aria-selected="false" data-status="closed">Completed</button></div><label class="cs-search"><span>Search work order</span><input id="cs-search" type="search" placeholder="Enter work order number"></label><div id="cs-records" role="status">'+empty('Loading requests…')+'</div></main>';}
    else if(part==='ticket'){title='Work order details';back=root+'/progress';body='<main class="cs-content"><div id="cs-records" role="status">'+empty('Loading request…')+'</div></main>';}
    else if(['deposit','withdrawal'].includes(part)&&sub!=='request'){title=part==='deposit'?'Recharge History':'Withdrawal History';body='<main class="cs-content"><div id="cs-records" role="status">'+empty('Loading records…')+'</div><p class="cs-hint">Cannot find your order?</p>'+(part==='deposit'?'':button('Submit a request',root+'/'+part+'/request'))+`<a class="cs-text-link" href="#/${part==='deposit'?'deposit':'withdraw'}/history">Open payment history ›</a></main>`;}
    else if(labels[part]){if(sub==='request')back=root+'/'+part;if(sub==='contact'&&rebind.includes(part)){title=part==='upi-rebind'?'Self-service UPI Delete & Rebind':labels[part];body='<main class="cs-content">'+otpView(part)+'</main>';}else body='<main class="cs-content">'+form(part,part==='deposit'?'signed-in':sub==='manual'?'manual':mode)+'</main>';}
    else body='<main class="cs-content">'+empty('Page not found')+button('Back to support',root)+'</main>';
    return `<section class="cs-page">${header(title,back,part!=='official')}${body}</section>`;
  }
  function modal(page,title,content){const d=document.createElement('dialog');d.className='cs-dialog';d.innerHTML=`<button class="cs-dialog-close" aria-label="Close">×</button><h2>${title}</h2>${content}`;page.append(d);d.querySelector('.cs-dialog-close').onclick=()=>d.close();d.onclick=e=>{if(e.target===d)d.close();};d.onclose=()=>d.remove();d.showModal();return d;}
  async function bind(route,toast){
    if(route===root+'/password'||route.startsWith(root+'/password/'))return window.ColorWinAccount.bind('#/account/settings/password',toast);
    const page=document.querySelector('.cs-page'),part=route.replace(root,'').split('/').filter(Boolean)[0];
    const languageButton=page.querySelector('[data-language]');if(languageButton)languageButton.onclick=()=>modal(page,'Language','<p class="cs-language">🇺🇸 English <b>✓</b></p>');
    page.querySelectorAll('[data-choice]').forEach(a=>{a.href=root+'/'+a.dataset.choice+'/manual';});
    const otpSend=page.querySelector('#cs-otp-send');if(otpSend)otpSend.onclick=()=>toast('SMS verification is not enabled yet. Please use manual verification.',true);
    const formEl=page.querySelector('#cs-request');
    if(formEl){
      const bankButton=page.querySelector('#cs-choose-bank');
      if(bankButton)bankButton.onclick=()=>window.ColorWinWallet.bankPicker(page,formEl.elements.bank_name.value,name=>{formEl.elements.bank_name.value=name;bankButton.querySelector('span').textContent=name;bankButton.classList.add('has-value');bankButton.removeAttribute('aria-invalid');});
      const files=new Map();page.querySelectorAll('input[type=file]').forEach(input=>input.onchange=()=>{const file=input.files[0],info=page.querySelector(`[data-file-info="${input.name}"]`);if(!file){files.delete(input.name);info.textContent='';return;}if(!validFile(input.name,file)){input.value='';files.delete(input.name);info.textContent='';toast('Choose a supported '+(input.name==='statement'?'PDF':input.name==='video'?'video':'image')+' file up to '+fileSpec(input.name).mb+' MB.',true);return;}files.set(input.name,file);info.textContent=file.name+' · '+(file.size/1024/1024).toFixed(2)+' MB';});
      if(formEl.dataset.topic==='deposit'){
        const submit=formEl.querySelector('[type=submit]'),status=page.querySelector('[data-deposit-status]');submit.disabled=true;
        (async()=>{try{const data=preview()?{deposits:[]}:await window.ColorWinAuth.accountRpc('colorwin_support_data');if(!formEl.isConnected)return;const id=route.split('/')[4];const order=(data.deposits||[]).find(d=>d.id===id&&['pending','to be paid','cancelled'].includes(d.status));
          if(!order){status.innerHTML='Please select an eligible deposit from <a class="cs-text-link" href="'+root+'/deposit">deposit history</a>.';return;}
          formEl.elements.deposit_id.value=order.id;formEl.elements.order_number.value=order.number;formEl.elements.amount.value=Number(order.amount).toFixed(2);formEl.elements.receiver_upi.value=order.recipient_upi||'';formEl.elements.utr.value=order.utr||'';status.hidden=true;
          const aged=Date.now()-new Date(order.created_at).getTime()>=86400000;const section=formEl.querySelector('[data-aged-proof]');section.hidden=!aged;for(const name of ['video','statement'])formEl.elements[name].required=aged;submit.disabled=false;
        }catch{if(formEl.isConnected)status.textContent='Could not load this order. Reopen the deposit from history.';}})();
      }

      const message=formEl.elements.message;if(message)message.oninput=()=>page.querySelector('.cs-counter').textContent=message.value.length+'/500';
      formEl.onsubmit=async e=>{e.preventDefault();if(bankButton&&!formEl.elements.bank_name.value){bankButton.setAttribute('aria-invalid','true');bankButton.focus();toast('Please select a bank name.',true);return;}if(preview()){toast('Sign in to submit a support request. Preview does not send work orders.',true);return;}const submit=formEl.querySelector('[type=submit]');submit.disabled=true;submit.textContent='Submitting…';const attachments=[];let committed=false;
        try{const details={verification_method:formEl.dataset.mode};for(const input of formEl.querySelectorAll('input:not([type=file]),textarea,select'))details[input.name]=input.value.trim();if(details.ifsc)details.ifsc=details.ifsc.toUpperCase();if(details.message&&details.message.length<10)throw Error('Describe the issue in at least 10 characters.');
          for(const [label,file] of files){if(!validFile(label,file))throw Error('Unsupported file type or size.');const ext=({ 'image/jpeg':'jpg','image/png':'png','image/webp':'webp','video/mp4':'mp4','video/quicktime':'mov','video/x-msvideo':'avi','video/x-matroska':'mkv','video/x-ms-wmv':'wmv','application/pdf':'pdf'})[file.type];const path=window.ColorWinAuth.session.user.id+'/'+crypto.randomUUID()+'.'+ext;await window.ColorWinAuth.supportUpload(path,file);attachments.push({path,label,name:file.name,size:file.size});}
          const ticket=await window.ColorWinAuth.accountRpc('colorwin_support_submit',{p_category:formEl.dataset.topic,p_details:details,p_attachments:attachments});committed=true;toast('Request submitted · '+ticket.number);location.hash=root+'/ticket/'+ticket.id;
        }catch(error){if(!committed&&attachments.length)await window.ColorWinAuth.supportRemove(attachments.map(a=>a.path)).catch(()=>{});toast(error.message||'Request could not be submitted. Please retry.',true);}finally{submit.disabled=false;submit.textContent='Confirm';}
      };
    }
    const records=page.querySelector('#cs-records');if(!records)return;let status='all',data={tickets:[],deposits:[]};
    const paint=()=>{if(!page.isConnected)return;if(part==='progress'){const needle=(page.querySelector('#cs-search').value||'').toLowerCase();const rows=data.tickets.filter(t=>(!needle||t.number.toLowerCase().includes(needle))&&(status==='all'||(status==='closed')===['resolved','rejected'].includes(t.status)));records.innerHTML=rows.length?rows.map(t=>`<a class="cs-ticket cs-card" href="${root}/ticket/${t.id}"><div><strong>${esc(labels[t.category])}</strong><span class="cs-badge ${esc(t.status)}">${esc(t.status)}</span></div><p>${esc(t.number)}</p><time>${esc(new Date(t.created_at).toLocaleString('en-IN'))}</time><span class="cs-ticket-arrow">›</span></a>`).join('')+'<p class="cs-end">No more data</p>':empty();}
      if(part==='ticket'){const id=route.split('/').pop(),t=data.tickets.find(t=>t.id===id);records.innerHTML=t?`<section class="cs-card"><div class="cs-ticket-title"><h2>${esc(labels[t.category])}</h2><span class="cs-badge ${esc(t.status)}">${esc(t.status)}</span></div><p class="cs-order-number">${esc(t.number)}</p><time>${esc(new Date(t.created_at).toLocaleString('en-IN'))}</time><dl class="cs-details">${Object.entries(t.details).map(([k,v])=>`<div><dt>${esc(k.replaceAll('_',' '))}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>${t.attachments.length?'<h3>Attachments</h3>'+t.attachments.map((a,i)=>`<button class="cs-attachment" data-attachment="${i}">${esc(a.label.replaceAll('_',' '))} · ${esc(a.name)} ↗</button>`).join(''):''}</section><section class="cs-card"><h2>Support response</h2><p>${esc(t.admin_reply||'Your request is awaiting review. Any reply from support will appear here.')}</p></section>`:empty('Work order not found');records.querySelectorAll('[data-attachment]').forEach(b=>b.onclick=async()=>{try{const a=t.attachments[Number(b.dataset.attachment)],url=await window.ColorWinAuth.supportUrl(a.path);const d=modal(page,'Attachment',`<a class="cs-text-link" href="${esc(url)}" target="_blank" rel="noopener">Open attachment ↗</a>`);if(!['mp4','mov','avi','mkv','wmv','pdf'].includes(a.path.split('.').pop()))d.insertAdjacentHTML('beforeend',`<img class="cs-attachment-preview" src="${esc(url)}" alt="Uploaded attachment">`);}catch{toast('Attachment could not be opened.',true);}});}
      if(['deposit','withdrawal'].includes(part)){const deposits=part==='deposit'?(data.deposits||[]).filter(d=>['pending','to be paid','cancelled'].includes(d.status)):[];records.innerHTML=deposits.length?deposits.map(d=>`<section class="cs-card cs-payment"><div><strong>Deposit</strong><span class="cs-badge ${esc(d.status==='cancelled'?'rejected':'pending')}">${esc(d.status==='to be paid'?'To be paid':d.status==='cancelled'?'Cancelled':'Pending')}</span></div><dl class="cs-details"><div><dt>Amount</dt><dd>₹${Number(d.amount).toFixed(2)}</dd></div><div><dt>Time</dt><dd>${esc(new Date(d.created_at).toLocaleString('en-IN'))}</dd></div><div><dt>Order Number</dt><dd>${esc(d.number)}</dd></div></dl><a class="cs-primary" href="${root}/deposit/request/${encodeURIComponent(d.id)}">Submit Deposit Voucher</a></section>`).join('')+'<p class="cs-end">No more data</p>':empty(part==='deposit'?'No pending, to-be-paid or cancelled deposits. Completed deposits do not need a missing-deposit request.':undefined);}

    };
    page.querySelectorAll('[data-status]').forEach(b=>b.onclick=()=>{status=b.dataset.status;page.querySelectorAll('[data-status]').forEach(el=>el.setAttribute('aria-selected',String(el===b)));paint();});const search=page.querySelector('#cs-search');if(search)search.oninput=paint;
    try{if(!preview())data=await window.ColorWinAuth.accountRpc('colorwin_support_data');paint();}catch{if(page.isConnected)records.innerHTML='<p class="cs-error" role="alert">Records could not be loaded. Please reopen this page to retry.</p>';}
  }
  const validSupportRoute=r=>{
    if(r===root||[root+'/faq',root+'/official',root+'/progress'].includes(r))return true;
    const parts=r.slice(root.length+1).split('/');
    const [part,sub,extra]=parts;
    if(part==='ticket')return parts.length===2&&/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(sub||'');
    if(!labels[part])return false;
    if(parts.length===1)return true;
    if(parts.length===2&&['manual','request'].includes(sub))return true;
    if(parts.length===3&&part==='deposit'&&sub==='request'&&/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(extra||''))return true;
    return parts.length===2&&sub==='contact'&&rebind.includes(part);
  };
  window.ColorWinSupport={matches:validSupportRoute,view,bind};
})();
